import{_ as a,o as t,c as o,a2 as i}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_08_01_contract.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_08_02_exec.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_08_03_reliability.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_08_04_action.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_08_05_scheduled.png",d="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_08_06_audit.png",q=JSON.parse('{"title":"让 Codex 自动干活：codex exec、GitHub Action 与定时任务完整指南","description":"交互会话中，人可以随时纠正代理；进入脚本、CI 和定时任务后，系统必须提前定义输入、权限、输出、失败状态和重复执行语义。自动化的成熟标志不是“没人看”，而是每一步都可以被机器判断、被人复盘。","frontmatter":{"title":"让 Codex 自动干活：codex exec、GitHub Action 与定时任务完整指南","description":"交互会话中，人可以随时纠正代理；进入脚本、CI 和定时任务后，系统必须提前定义输入、权限、输出、失败状态和重复执行语义。自动化的成熟标志不是“没人看”，而是每一步都可以被机器判断、被人复盘。","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":4,"source":"2026-08-10/ai_codex_official_08_automation.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_08_01_contract.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"让 Codex 自动干活：codex exec、GitHub Action 与定时任务完整指南"}],["meta",{"property":"og:description","content":"交互会话中，人可以随时纠正代理；进入脚本、CI 和定时任务后，系统必须提前定义输入、权限、输出、失败状态和重复执行语义。自动化的成熟标志不是“没人看”，而是每一步都可以被机器判断、被人复盘。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_08_01_contract.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"让 Codex 自动干活：codex exec、GitHub Action 与定时任务完整指南"}],["meta",{"name":"twitter:description","content":"交互会话中，人可以随时纠正代理；进入脚本、CI 和定时任务后，系统必须提前定义输入、权限、输出、失败状态和重复执行语义。自动化的成熟标志不是“没人看”，而是每一步都可以被机器判断、被人复盘。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_08_01_contract.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-08-automation.md","filePath":"archive/ai-codex-official-08-automation.md","lastUpdated":null}'),h={name:"archive/ai-codex-official-08-automation.md"};function p(_,e,u,x,m,b){return t(),o("div",null,[...e[0]||(e[0]=[i('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="让-codex-自动干活-codex-exec、github-action-与定时任务完整指南" tabindex="-1">让 Codex 自动干活：codex exec、GitHub Action 与定时任务完整指南 <a class="header-anchor" href="#让-codex-自动干活-codex-exec、github-action-与定时任务完整指南" aria-label="Permalink to &quot;让 Codex 自动干活：codex exec、GitHub Action 与定时任务完整指南&quot;">​</a></h1><p>交互会话中，人可以随时纠正代理；进入脚本、CI 和定时任务后，系统必须提前定义输入、权限、输出、失败状态和重复执行语义。自动化的成熟标志不是“没人看”，而是每一步都可以被机器判断、被人复盘。</p><h2 id="一、自动化之前先定义机器合同" tabindex="-1">一、自动化之前先定义机器合同 <a class="header-anchor" href="#一、自动化之前先定义机器合同" aria-label="Permalink to &quot;一、自动化之前先定义机器合同&quot;">​</a></h2><h3 id="_1-1-输入必须确定" tabindex="-1">1.1 输入必须确定 <a class="header-anchor" href="#_1-1-输入必须确定" aria-label="Permalink to &quot;1.1 输入必须确定&quot;">​</a></h3><p>仓库版本、任务文本、相关文件和环境都应可重建。依赖临时聊天、未提交文件或人工选择的流程不能直接搬进 CI。</p><h3 id="_1-2-输出必须可消费" tabindex="-1">1.2 输出必须可消费 <a class="header-anchor" href="#_1-2-输出必须可消费" aria-label="Permalink to &quot;1.2 输出必须可消费&quot;">​</a></h3><p>自然语言总结适合人阅读，后续程序需要结构化事件、指定输出文件和稳定 Schema。关键结论不能靠脆弱的字符串匹配提取。</p><h3 id="_1-3-退出状态必须真实" tabindex="-1">1.3 退出状态必须真实 <a class="header-anchor" href="#_1-3-退出状态必须真实" aria-label="Permalink to &quot;1.3 退出状态必须真实&quot;">​</a></h3><p>任务失败却返回成功，会让流水线产生假绿灯。调用方要区分模型未完成、工具失败、验证失败和环境故障。</p><h3 id="_1-4-权限必须按阶段拆分" tabindex="-1">1.4 权限必须按阶段拆分 <a class="header-anchor" href="#_1-4-权限必须按阶段拆分" aria-label="Permalink to &quot;1.4 权限必须按阶段拆分&quot;">​</a></h3><p>只读分析、生成补丁、上传产物、评论 Pull Request 和发布不应共享同一最高权限。</p><p><img src="'+r+'" alt="图 1：输入、权限、输出与退出状态组成自动化合同"></p><h2 id="二、codex-exec-是非交互执行核心" tabindex="-1">二、codex exec 是非交互执行核心 <a class="header-anchor" href="#二、codex-exec-是非交互执行核心" aria-label="Permalink to &quot;二、codex exec 是非交互执行核心&quot;">​</a></h2><h3 id="_2-1-它面向脚本而不是持续对话" tabindex="-1">2.1 它面向脚本而不是持续对话 <a class="header-anchor" href="#_2-1-它面向脚本而不是持续对话" aria-label="Permalink to &quot;2.1 它面向脚本而不是持续对话&quot;">​</a></h3><p><code>codex exec</code> 接收任务后独立运行，适合批量审计、固定报告、CI 诊断和后台 Job。需要多轮连续上下文时，应显式管理会话或使用 SDK。</p><h3 id="_2-2-标准输出与标准错误要分工" tabindex="-1">2.2 标准输出与标准错误要分工 <a class="header-anchor" href="#_2-2-标准输出与标准错误要分工" aria-label="Permalink to &quot;2.2 标准输出与标准错误要分工&quot;">​</a></h3><p>机器结果、事件流和最终文件应有稳定位置，诊断信息进入可追踪日志。调用方不能假设所有文字都属于成功结果。</p><h3 id="_2-3-sandbox-与-approval-仍然生效" tabindex="-1">2.3 Sandbox 与 Approval 仍然生效 <a class="header-anchor" href="#_2-3-sandbox-与-approval-仍然生效" aria-label="Permalink to &quot;2.3 Sandbox 与 Approval 仍然生效&quot;">​</a></h3><p>非交互不等于全权限。自动化应使用预先批准的 Profile 或策略，无法获得的能力必须明确失败，而不是等待无人响应的提示。</p><p><img src="'+c+'" alt="图 2：任务输入经过 codex exec 形成事件、文件与退出状态"></p><h2 id="三、重试、超时与幂等由调用方负责" tabindex="-1">三、重试、超时与幂等由调用方负责 <a class="header-anchor" href="#三、重试、超时与幂等由调用方负责" aria-label="Permalink to &quot;三、重试、超时与幂等由调用方负责&quot;">​</a></h2><h3 id="_3-1-超时要覆盖外部工具" tabindex="-1">3.1 超时要覆盖外部工具 <a class="header-anchor" href="#_3-1-超时要覆盖外部工具" aria-label="Permalink to &quot;3.1 超时要覆盖外部工具&quot;">​</a></h3><p>依赖安装、构建、测试和网络可能长期阻塞。超时后应保留已完成阶段和失败证据。</p><h3 id="_3-2-重试要区分故障类型" tabindex="-1">3.2 重试要区分故障类型 <a class="header-anchor" href="#_3-2-重试要区分故障类型" aria-label="Permalink to &quot;3.2 重试要区分故障类型&quot;">​</a></h3><p>网络瞬时错误可以重试，确定性测试失败不应反复消耗计算。重试前要确认是否已有外部副作用。</p><h3 id="_3-3-幂等避免重复状态" tabindex="-1">3.3 幂等避免重复状态 <a class="header-anchor" href="#_3-3-幂等避免重复状态" aria-label="Permalink to &quot;3.3 幂等避免重复状态&quot;">​</a></h3><p>同一任务重复运行不能生成多个相同评论、分支、Issue 或部署。外层系统使用任务键和状态存储控制重复。</p><p><img src="'+l+'" alt="图 3：超时、故障分类、重试与幂等组成恢复策略"></p><h2 id="四、github-action-把-codex-放进-ci" tabindex="-1">四、GitHub Action 把 Codex 放进 CI <a class="header-anchor" href="#四、github-action-把-codex-放进-ci" aria-label="Permalink to &quot;四、GitHub Action 把 Codex 放进 CI&quot;">​</a></h2><h3 id="_4-1-从只读-review-开始" tabindex="-1">4.1 从只读 Review 开始 <a class="header-anchor" href="#_4-1-从只读-review-开始" aria-label="Permalink to &quot;4.1 从只读 Review 开始&quot;">​</a></h3><p>Action 可以审查 Pull Request、生成报告或补丁。低风险起点是只读仓库并输出发现，不直接持有推送和合并权限。</p><h3 id="_4-2-workflow-权限比-prompt-更强" tabindex="-1">4.2 Workflow 权限比 Prompt 更强 <a class="header-anchor" href="#_4-2-workflow-权限比-prompt-更强" aria-label="Permalink to &quot;4.2 Workflow 权限比 Prompt 更强&quot;">​</a></h3><p>即使 Prompt 写着“只分析”，Job 若持有写权限和 Secrets，事故半径仍然扩大。<code>permissions</code>、Checkout、Secret 和 Sandbox 必须显式收口。</p><h3 id="_4-3-prompt-文件进入版本控制" tabindex="-1">4.3 Prompt 文件进入版本控制 <a class="header-anchor" href="#_4-3-prompt-文件进入版本控制" aria-label="Permalink to &quot;4.3 Prompt 文件进入版本控制&quot;">​</a></h3><p>固定自动化说明应与代码一起 Review，模型、推理强度、输出位置和验证命令都应可追踪。</p><h3 id="_4-4-写回动作放在后续-job" tabindex="-1">4.4 写回动作放在后续 Job <a class="header-anchor" href="#_4-4-写回动作放在后续-job" aria-label="Permalink to &quot;4.4 写回动作放在后续 Job&quot;">​</a></h3><p>分析、补丁、评论和合并使用不同阶段与权限。只有前置检查通过，后续动作才获得必要能力。</p><p><img src="'+n+'" alt="图 4：GitHub 事件经过最小权限 Codex Job 产出审查结果"></p><h2 id="五、scheduled-tasks-只自动化稳定流程" tabindex="-1">五、Scheduled Tasks 只自动化稳定流程 <a class="header-anchor" href="#五、scheduled-tasks-只自动化稳定流程" aria-label="Permalink to &quot;五、Scheduled Tasks 只自动化稳定流程&quot;">​</a></h2><h3 id="_5-1-周期任务需要明确时间与环境" tabindex="-1">5.1 周期任务需要明确时间与环境 <a class="header-anchor" href="#_5-1-周期任务需要明确时间与环境" aria-label="Permalink to &quot;5.1 周期任务需要明确时间与环境&quot;">​</a></h3><p>任务的时区、频率、仓库、输入和通知目标必须显式。计划本身不能依赖某个临时 Thread 的隐含背景。</p><h3 id="_5-2-无变化也是合法结果" tabindex="-1">5.2 无变化也是合法结果 <a class="header-anchor" href="#_5-2-无变化也是合法结果" aria-label="Permalink to &quot;5.2 无变化也是合法结果&quot;">​</a></h3><p>巡检、报告和监控经常没有新发现。系统应区分“没有变化”“执行失败”和“需要人工处理”。</p><h3 id="_5-3-连续失败要升级" tabindex="-1">5.3 连续失败要升级 <a class="header-anchor" href="#_5-3-连续失败要升级" aria-label="Permalink to &quot;5.3 连续失败要升级&quot;">​</a></h3><p>反复重试不能替代处理。达到阈值后停止同方向消耗，保留证据并通知责任人。</p><p><img src="'+s+'" alt="图 5：定时触发、执行、结果分类与人工升级闭环"></p><h2 id="六、自动化交付必须保留审计证据" tabindex="-1">六、自动化交付必须保留审计证据 <a class="header-anchor" href="#六、自动化交付必须保留审计证据" aria-label="Permalink to &quot;六、自动化交付必须保留审计证据&quot;">​</a></h2><p>记录任务来源、仓库提交、配置、工具事件、批准、输出、测试与最终状态。审计不需要保存模型全部内部推理，但必须能够解释外部状态为何改变。</p><p><img src="'+d+'" alt="图 6：任务来源、执行事件、验证与外部状态形成审计链"></p><h2 id="七、官方参考资料" tabindex="-1">七、官方参考资料 <a class="header-anchor" href="#七、官方参考资料" aria-label="Permalink to &quot;七、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/non-interactive-mode" target="_blank" rel="noreferrer">OpenAI Docs：Non-interactive mode</a></p><p><a href="https://learn.chatgpt.com/docs/github-action" target="_blank" rel="noreferrer">OpenAI Docs：GitHub Action</a></p><p><a href="https://learn.chatgpt.com/docs/automations" target="_blank" rel="noreferrer">OpenAI Docs：Scheduled tasks</a></p>',54)])])}const k=a(h,[["render",p]]);export{q as __pageData,k as default};
